function gustAt(t){return Math.sin(t*2.35)*(.72+.28*Math.sin(t*.53+.8))*.8+Math.sin(t*4.1+.6)*.2}
function windLoads(loads,gust){const side=nodes.map(()=>0),used=new Set(members.flatMap(m=>[m.a,m.b])),deckNodes=roadNodes();for(const i of used){if(nodes[i].fixed)continue;const shape=Math.max(0,Math.sin((nodes[i].x-gapLeft())*Math.PI/(gapRight()-gapLeft())));const deck=deckNodes.has(i);loads[i]+=gust*(deck?240:25)*shape;side[i]=gust*(deck?130:20)*shape}return side}
function structuralStep(dt){const loads=trainLoads(x);windClock+=dt;const target=storm?gustAt(windClock):0;windLevel+=(target-windLevel)*Math.min(1,dt*9);const s=solve(loads,windLoads(loads,windLevel));if(!s)return;memberStress=s.ratios;materialForces=s.forces;let max=0;const deck=roadNodes();nodes.forEach((n,i)=>{const tx=s.u[2*i],ty=s.u[2*i+1];if(n.fixed){displacement[i].x=displacement[i].y=0;swayVelocity[i].x=swayVelocity[i].y=0;return}for(const axis of ['x','y']){const target=Math.max(-80,Math.min(80,axis==='x'?tx:ty));if(storm||Math.abs(windLevel)>.01){swayVelocity[i][axis]+=(110*(target-displacement[i][axis])-8*swayVelocity[i][axis])*dt;displacement[i][axis]+=swayVelocity[i][axis]*dt}else{displacement[i][axis]+=(target-displacement[i][axis])*Math.min(1,dt*12);swayVelocity[i][axis]=0}}if(deck.has(i))max=Math.max(max,Math.hypot(tx,ty),Math.hypot(displacement[i].x,displacement[i].y))});const peak=Math.max(0,...memberStress);runPeak=Math.max(runPeak,peak);runDeflection=Math.max(runDeflection,max);memberStress.forEach((v,i)=>report[i]=Math.max(report[i]||0,v));$('load').textContent='НАГРУЗКА '+Math.round(peak*100)+'% · ПРОГИБ '+Math.round(max)+(storm?' · ВЕТЕР '+(windLevel<0?'← ':'→ ')+Math.round(Math.abs(windLevel)*100)+'%':'');if(peak>1||max>32){broken=0;let worst=-1;roadPath.forEach((e,i)=>{const score=Math.hypot(s.u[2*e.a],s.u[2*e.a+1])+Math.hypot(s.u[2*e.b],s.u[2*e.b+1]);if(score>worst){worst=score;broken=i}});mode='fall';startWreck();const failed=members[memberStress.indexOf(peak)];failureReason=peak>1?({road:'Дорожное полотно перегружено. Усиль его балками и диагоналями.',wood:'Деревянная балка раскололась от перегрузки.',steel:'Стальная балка деформировалась от перегрузки.',cable:'Трос порвался от натяжения.'}[failed?.type]||'Соединение перегружено.'):'Дорога сильно сместилась. Свяжи её узлы с берегами и добавь диагонали.';if(storm)failureReason+=' При испытании действовали порывы ветра.';say('Конструкция не выдержала нагрузки.')}}
