function timber(length,seed,jagged=false,crack=0){const half=Math.max(5.5,3/scale),g=c.createLinearGradient(0,-half,0,half);g.addColorStop(0,'#e7bd7e');g.addColorStop(.25,'#b77d43');g.addColorStop(.65,'#bc8b50');g.addColorStop(1,'#69462e');const edge=jagged?[[length-7,-half],[length+3,-half*.65],[length-5,-half*.25],[length+6,0],[length-4,half*.4],[length+2,half]]:[[length,-half],[length,half]];path([[0,-half],...edge,[0,half]],g,'#4c3b2b',1.4);for(let j=0;j<4;j++){const y=-half+2+j*(half*2-4)/3;c.beginPath();c.moveTo(3,y);c.bezierCurveTo(length*.32,y+Math.sin(seed+j)*2,length*.66,y-1,length-9,y+.8);c.strokeStyle=j%2?'#efc48866':'#5e3d2866';c.lineWidth=.7;c.stroke()}const knot=length*(.28+rand(seed)*.35);ellipse(knot,.5,4,1.8,'#754c2f');ellipse(knot,.5,1.8,.8,'#3c3027');for(const xx of [5,length-5]){ellipse(xx,0,1.6,1.6,'#454b44');ellipse(xx-.4,-.5,.6,.6,'#c7c9a7')}if(crack>0){const mid=length*.52;path([[mid-5,-half],[mid-1,-1],[mid-4,1],[mid+3,half*crack]],null,'#3c2921',1.4);line(mid+1,1,mid+12,2,'#5e3925',1)}}
function steelBeam(length,bend=0){const half=Math.max(5,2.6/scale),g=c.createLinearGradient(0,-half,0,half);g.addColorStop(0,'#e4eef0');g.addColorStop(.2,'#aab9c0');g.addColorStop(.25,'#516776');g.addColorStop(.7,'#718994');g.addColorStop(.78,'#d6e6e5');g.addColorStop(1,'#3a505e');c.beginPath();c.moveTo(0,0);c.quadraticCurveTo(length*.5,bend,length,0);c.strokeStyle='#223b48';c.lineWidth=half*2+2;c.stroke();c.strokeStyle=g;c.lineWidth=half*2;c.stroke();c.strokeStyle='#e9f0e899';c.lineWidth=1;c.stroke();for(let q=.06;q<1;q+=.15){const xx=length*q,yy=2*(1-q)*q*bend;ellipse(xx,yy,1.8,1.8,'#344953');ellipse(xx-.5,yy-.6,.7,.7,'#eef6ec')}if(Math.abs(bend)>12){line(length*.46,bend*.49-3,length*.55,bend*.49+3,'#34414b',1.5)}}
function cableCurve(a,b,sag=0,frayed=false){c.save();c.lineCap='round';c.beginPath();c.moveTo(a.x,a.y);c.quadraticCurveTo((a.x+b.x)/2,(a.y+b.y)/2+sag,b.x,b.y);c.strokeStyle='#172c35';c.lineWidth=Math.max(5,3/scale);c.stroke();c.strokeStyle='#8b9b9f';c.lineWidth=Math.max(3,1.8/scale);c.stroke();c.setLineDash([2.2,3.8]);c.strokeStyle='#e6e5c9';c.lineWidth=Math.max(1.3,.8/scale);c.stroke();c.setLineDash([]);if(frayed){const angle=Math.atan2(b.y-a.y,b.x-a.x);for(let j=-1;j<=1;j++)line(b.x,b.y,b.x+Math.cos(angle+j*.3)*9,b.y+Math.sin(angle+j*.3)*9,'#bcc9c5',.9)}c.restore()}
function roadBeam(L){line(0,0,L,0,'#3d392f',9);for(let xx=3;xx<L;xx+=11){line(xx,-5,xx,4,'#b69c6c',5);line(xx-1,-5,xx-1,4,'#e4c38a',1)}line(0,-2,L,-2,'#384f58',4);line(0,-3,L,-3,'#d5e4df',1.5)}
function materialMember(m,i){const a=nodePosition(m.a),b=nodePosition(m.b),dx=b.x-a.x,dy=b.y-a.y,L=Math.hypot(dx,dy),ratio=mode==='test'?(memberStress[i]||0):survey?(report[i]||0):0;if(mode==='test'||survey){const col=ratio>.9?'#ff7358':ratio>.65?'#f1c560':'#8ee0b6';c.save();c.globalAlpha=.6;line(a.x,a.y,b.x,b.y,col,Math.max(16,8/scale));c.restore()}const fracture=fractures.get(i);if(fracture&&fall>=fracture.delay){drawFracture(fracture);return}if(m.type==='cable'){const force=materialForces[i]||0,sag=mode==='test'?(force>0?Math.max(.3,7/(1+ratio*35)):10):7;const vibration=mode==='test'&&!reducedMotion.matches?Math.sin(time*12+i)*Math.sin(time*2+i)*Math.min(3,L/100)/(1+ratio*12)*(storm?1.5:.5):0;cableCurve(a,b,sag+vibration);return}c.save();c.translate(a.x,a.y);c.rotate(Math.atan2(dy,dx));if(m.type==='road')roadBeam(L);else if(m.type==='wood')timber(L,m.a*23+m.b,false,mode==='test'&&ratio>.8?Math.min(1,(ratio-.8)*5):0);else steelBeam(L,mode==='test'&&(materialForces[i]||0)<0?Math.max(0,ratio-.65)*20:0);c.restore()}
function prepareFractures(){fractures.clear();const {left,right}=brokenSpan();members.forEach((m,i)=>{const a=nodePosition(m.a),b=nodePosition(m.b),overload=(memberStress[i]||0)>1,touches=Math.max(a.x,b.x)>=left&&Math.min(a.x,b.x)<=right;const attached=roadNodes().has(m.a)||roadNodes().has(m.b)||Math.abs(displacement[m.a].y)>5||Math.abs(displacement[m.b].y)>5;if(!overload&&!(touches&&attached))return;const delay=overload?0:.08+rand(i+51)*.2;fractures.set(i,{i,type:m.type,a:{...a},b:{...b},delay,seed:m.a*23+m.b});const count=m.type==='wood'||m.type==='road'?9:m.type==='steel'?3:0;for(let j=0;j<count;j++)debris.push({type:m.type,delay,x:(a.x+b.x)/2,y:(a.y+b.y)/2,vx:(rand(i*31+j+80)-.5)*120,vy:-30-rand(j+i*17)*70,a:rand(j+1)*6,spin:(rand(i+j+50)-.5)*9,size:m.type==='wood'?5+rand(j)*14:3+rand(j)*4})})}
function drawFracture(f){fractureDust(f);const t=Math.max(0,fall-f.delay),a=f.a,b=f.b,dx=b.x-a.x,dy=b.y-a.y,L=Math.hypot(dx,dy),angle=Math.atan2(dy,dx);if(f.type==='wood'||f.type==='road'){for(let side=0;side<2;side++){const anchor=side?b:a,detached=Math.max(0,t-.22);c.save();c.translate(anchor.x+(side?1:-1)*detached*18,anchor.y+150*detached*detached);c.rotate(angle+(side?Math.PI:0)+(side?-1:1)*Math.min(t*1.4,1.1));timber(L*.46,f.seed+side,true);c.restore()}}else if(f.type==='steel'){const detached=Math.max(0,t-.7);c.save();c.translate(a.x+detached*12,a.y+150*detached*detached);c.rotate(angle+Math.min(t*.1,.35));steelBeam(L,Math.min(60,t*80));c.restore()}else{for(let side=0;side<2;side++){const anchor=side?b:a,sign=side?-1:1,release=1-Math.exp(-t*9),swing=reducedMotion.matches?0:Math.sin(t*17+side)*Math.exp(-t*2.8)*L*.12;const tip={x:anchor.x+dx*sign*.43*(1-release*.65)+swing,y:anchor.y+dy*sign*.43*(1-release*.65)+Math.min(L*.4,t*t*80)};cableCurve(anchor,tip,sign*swing*.7,true)}}}

function nodePosition(i){return{x:nodes[i].x+displacement[i].x,y:nodes[i].y+displacement[i].y}}
function bridge(){if(mode==='build'&&$('grid').checked&&(material==='node'||activePointer!==null)){for(let xx=gapLeft();xx<=gapRight();xx+=20)for(let yy=190;yy<=510;yy+=20)if(availablePoint({x:xx,y:yy}))ellipse(xx,yy,.9/scale,.9/scale,'#eff4d83b')}if(lastBuild&&mode==='build'&&!reducedMotion.matches&&time-lastBuild.at<.65){const age=time-lastBuild.at;for(const id of [lastBuild.a,lastBuild.b]){const n=nodes[id];if(!n)continue;for(let j=0;j<8;j++){const angle=j*TAU/8,r=(8+age*35)/scale;ellipse(n.x+Math.cos(angle)*r,n.y+Math.sin(angle)*r,1.7/scale,1.7/scale,`rgba(255,227,154,${1-age/.65})`)}}}if(hints&&mode==='build'){c.save();c.strokeStyle='#b5e5da33';c.lineWidth=1/scale;for(const n of nodes){line(n.x,200,n.x,500,'#d0eee222',1/scale);line(280,n.y,920,n.y,'#d0eee222',1/scale)}c.restore()}
members.forEach((m,i)=>{if(m.type!=='road')materialMember(m,i)});members.forEach((m,i)=>{if(m.type==='road')materialMember(m,i)});
if(hints&&mode==='build'){c.save();c.setLineDash([7,6]);line(gapLeft(),350,gapRight(),350,'#ffe0a299',3);for(let i=0;i<6;i++){line(gridX(i),470,gridX(i+1),470,'#ffe0a299',3);line(gridX(i),350,gridX(i+1),470,'#ffe0a299',3)}for(let i=1;i<6;i++)line(gridX(i),350,gridX(i),470,'#ffe0a299',3);c.restore()}
if(mode==='build'&&!roadPath.length){c.save();c.font=(9/scale)+'px system-ui';c.fillStyle='#ffe4a0';c.textAlign='left';c.fillText('ВЪЕЗД →',gapLeft()+17/scale,350-18/scale);c.textAlign='right';c.fillText('→ ВЫЕЗД',gapRight()-17/scale,350-18/scale);c.restore()}for(let i=0;i<nodes.length;i++){const n=nodePosition(i);if(!nodeVisible(i))continue;if(mode!=='build'&&!members.some(m=>m.a===i||m.b===i)&&!nodes[i].fixed)continue;const size=mode==='build'?Math.max(7,10/scale):4;if(mode==='build'){ellipse(n.x,n.y,(i===selected||i===hover?19:14)/scale,(i===selected||i===hover?19:14)/scale,i===selected?'#ffe4a080':i===hover?'#ffffff70':'#153b4260')}ellipse(n.x,n.y,size,size,nodes[i].fixed?'#f4cf83':i===selected?'#fff3b9':'#c3ddd0');ellipse(n.x,n.y,2.5,2.5,'#325b5b');if(nodes[i].fixed){c.strokeStyle='#f7dca5';c.lineWidth=2;c.strokeRect(n.x-size-3,n.y-size-3,size*2+6,size*2+6)}}
if(dragging&&gestureStart&&cursor&&materials[material]){c.save();c.setLineDash([6/scale,5/scale]);line(gestureStart.x,gestureStart.y,cursor.x,cursor.y,'#fff0a6',3/scale);c.restore()}if(cursor&&mode==='build'&&material!=='erase'){const p=cursor;ellipse(p.x,p.y,7/scale,7/scale,'#fff0a6');line(p.x-14/scale,p.y,p.x+14/scale,p.y,'#fff0a6',1/scale);line(p.x,p.y-14/scale,p.x,p.y+14/scale,'#fff0a6',1/scale)}if(selected!==null&&(hover!==null||cursor)){const a=nodes[selected],b=hover!==null?nodes[hover]:cursor;c.save();c.setLineDash([6/scale,5/scale]);line(a.x,a.y,b.x,b.y,'#fff0a6',3/scale);c.restore()}line(0,347,gapLeft(),347,'#c7c8a6',3);line(gapRight(),347,1200,347,'#c7c8a6',3)}
function point(e){const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale}}
function pickNode(e){const p=point(e);let best=null,dist=(e.pointerType==='mouse'?22:28)/scale;nodes.forEach((n,i)=>{if(!nodeVisible(i))return;const d=Math.hypot(n.x-p.x,n.y-p.y);if(d<dist){dist=d;best=i}});return best}
function eraseAt(e){const p=point(e);let best=-1,dist=(e.pointerType==='mouse'?14:24)/scale;members.forEach((m,i)=>{const a=nodes[m.a],b=nodes[m.b],dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy))),d=Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);if(d<dist){dist=d;best=i}});if(best<0){const i=pickNode(e);if(i!==null&&!nodes[i].fixed&&!members.some(m=>m.a===i||m.b===i)){history.push(snapshot());if(i<21)nodes[i].guide=true;else{nodes.splice(i,1);members.forEach(m=>{if(m.a>i)m.a--;if(m.b>i)m.b--})}syncNodes();roadPath=findRoadPath();hud();say('Свободный узел удалён.')}else say('Коснись середины элемента. Связанный узел удаляется после его балок.')}else deleteMember(best)}
function clearGesture(){activePointer=null;downAt=null;dragFrom=null;dragging=false;cursor=null;hover=null}
function snappedPoint(e){const hit=pickNode(e);if(hit!==null)return {...nodes[hit],id:hit};const p=point(e),step=20;let q=$('grid').checked?{x:gapLeft()+Math.round((p.x-gapLeft())/step)*step,y:350+Math.round((p.y-350)/step)*step}:{...p};let distance=12/scale;for(const m of members){const A=nodes[m.a],B=nodes[m.b],dx=B.x-A.x,dy=B.y-A.y,t=((p.x-A.x)*dx+(p.y-A.y)*dy)/(dx*dx+dy*dy);if(t<=.08||t>=.92)continue;const at={x:A.x+t*dx,y:A.y+t*dy},d=Math.hypot(at.x-p.x,at.y-p.y);if(d<distance){distance=d;q=at}}return q}
function connectPoints(start,end){const before=snapshot(),oldHistory=history.slice();const a=start.id??insertNode(start),b=end.id??insertNode(end);if(a===null||b===null||a===b){restoreSnapshot(before);history=oldHistory;hud();return false}if(material==='road'){const parts=memberSegments(a,b);for(const part of parts){const L=length(part.a,part.b);if(L<=materials.road.max)continue;const count=Math.ceil(L/110),A={...nodes[part.a]},B={...nodes[part.b]};for(let k=1;k<count;k++){if(insertNode({x:A.x+(B.x-A.x)*k/count,y:A.y+(B.y-A.y)*k/count})===null){restoreSnapshot(before);history=oldHistory;hud();return false}}}}const ok=addMember(a,b);if(!ok){restoreSnapshot(before);history=oldHistory;hud();return false}history=oldHistory;history.push(before);syncNodes();roadPath=findRoadPath();hud();return true}
function choosePoint(p){if(material==='node'){addNode(p);selected=null;return}if(selected===null){const id=p.id??addNode(p);if(id!==null){selected=id;say('Начало выбрано. Коснись конца линии или пустого места для нового узла.')}}else if(p.id===selected){selected=null;say('Выбор отменён.')}else{const start={...nodes[selected],id:selected};if(connectPoints(start,p))selected=null}}
cv.addEventListener('pointerdown',e=>{if(mode!=='build'||paused||activePointer!==null||e.isPrimary===false)return;if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();activePointer=e.pointerId;cv.setPointerCapture(e.pointerId);downAt={x:e.clientX,y:e.clientY};gestureStart=snappedPoint(e);dragFrom=gestureStart.id??null;hover=dragFrom;dragging=false;cursor=gestureStart});
cv.addEventListener('pointermove',e=>{if(mode!=='build'||paused||e.pointerId!==activePointer)return;cursor=snappedPoint(e);hover=cursor.id??null;const threshold=e.pointerType==='mouse'?7:12;if(downAt&&Math.hypot(e.clientX-downAt.x,e.clientY-downAt.y)>threshold)dragging=true;if(dragging&&material!=='erase'&&material!=='node'){const start=gestureStart,L=Math.hypot(cursor.x-start.x,cursor.y-start.y);say('Длина '+Math.round(L)+' · '+(cursor.id!==undefined?'соединение с узлом':'новый свободный узел'))}});
cv.addEventListener('pointerup',e=>{if(e.pointerId!==activePointer)return;if(mode==='build'&&!paused){if(material==='erase'){eraseAt(e);selected=null}else if(material==='node')addNode(snappedPoint(e));else if(dragging){connectPoints(gestureStart,snappedPoint(e));selected=null}else choosePoint(snappedPoint(e))}clearGesture()});
cv.addEventListener('pointercancel',e=>{if(e.pointerId===activePointer)clearGesture()});cv.addEventListener('lostpointercapture',e=>{if(e.pointerId===activePointer)clearGesture()});

function hud(){$('route').value=String(level);$('route').disabled=mode!=='build';$('survey').disabled=mode!=='build';$('survey').setAttribute('aria-pressed',String(survey));document.body.dataset.route=level;document.body.dataset.mode=mode;const L=levels[level];$('money').textContent=(L.budget-spent())+' / '+L.budget;$('level').textContent=String(level+1).padStart(2,'0')+' / 03';$('chapter').textContent=L.place;$('title').textContent=L.name;$('brief').textContent=L.brief;$('run').textContent=mode==='build'?'Запустить поезд →':'Вернуться к проекту';$('undo').disabled=mode!=='build'||!history.length;document.querySelectorAll('[data-material]').forEach(b=>b.disabled=mode!=='build');$('hint').disabled=mode!=='build';$('nodeStart').disabled=$('nodeEnd').disabled=$('connect').disabled=mode!=='build';$('connect').disabled=mode!=='build'||!materials[material];$('grid').disabled=mode!=='build';$('bays').textContent=survey?'НАГРУЗКА: зелёный — запас · жёлтый — высокая · красный — риск':members.length+' элементов · '+(roadPath.length?'дорога соединена':'дорога не соединена')+' · '+('★'.repeat(medals[level]||0)||'маршрут без медали')}
function say(t){$('status').textContent=t}
function reset(clear=false){if(clear)configureGorge();mode='build';paused=false;windClock=windLevel=0;swayVelocity=nodes.map(()=>({x:0,y:0}));broken=-1;fall=0;x=gapLeft()-50;acc=0;def.fill(0);smoke=[];wreck=[];couplers=[];debris=[];fractures.clear();materialForces=[];clearGesture();selected=null;displacement=nodes.map(()=>({x:0,y:0}));memberStress=[];if(clear){members=[];history=[];survey=false;report=[]}syncNodes();roadPath=findRoadPath();say('Начни с «Дороги»: соедини берега. Пустое место создаёт узел; балки и тросы укрепляют путь.');$('load').textContent='НАГРУЗКА —';hud()}
function show(tag,title,text,button,fn){$('modalTag').textContent=tag;$('modalTitle').textContent=title;$('modalText').textContent=text;$('continue').textContent=button;resultAction=fn;$('retry').hidden=mode!=='won';$('modal').showModal()}
$('continue').onclick=()=>{$('modal').close();resultAction?.()};$('modal').addEventListener('cancel',e=>{e.preventDefault();$('continue').click()});
function run(){if(paused)return;clearGesture();if(mode!=='build'){reset();return}roadPath=findRoadPath();if(!roadPath.length){say('Сначала соедини дорожным полотном два золотых узла у въезда и выезда. Балки и тросы не заменяют дорогу.');hud();return}selected=hover=null;mode='test';windClock=windLevel=0;swayVelocity=nodes.map(()=>({x:0,y:0}));report=[];survey=false;$('load').textContent='НАГРУЗКА —';runPeak=runDeflection=0;x=gapLeft()-50;broken=-1;fall=0;wreck=[];couplers=[];debris=[];fractures.clear();materialForces=[];def.fill(0);say(storm?'Испытание в бурю: ветер раскачивает мост и нагружает связи.':'Испытание началось. Следи за цветом ферм.');hud()}
function end(win){mode=win?'won':'lost';document.body.dataset.mode=mode;if(win){const stars=1+(spent()<=levels[level].budget*.95?1:0)+(runPeak<.85&&runDeflection<24?1:0);medals[level]=Math.max(medals[level]||0,stars);try{localStorage.setItem('mistBridgeFreeMedals',JSON.stringify(medals))}catch{}best=Math.max(best,level+1);try{localStorage.setItem('mistBridgeBest',best)}catch{}show('МАРШРУТ ОТКРЫТ',level===2?'Через туман.':'Поезд прибыл.',`${'★'.repeat(stars)}${'☆'.repeat(3-stars)} · 1 звезда за рейс, ещё по одной за экономию ≥5% и запас прочности (нагрузка <85%, прогиб <24). Пиковая нагрузка ${Math.round(runPeak*100)}%, прогиб ${Math.round(runDeflection)}. Все вагоны на другом берегу. Потрачено ${spent()} из ${levels[level].budget} монет. ${level===2?'Красный каньон пройден. Можно вернуться к другим ущельям.':'Впереди более тяжёлый состав.'}`,level===2?'Пройти заново':'Следующий маршрут',()=>{routeDrafts[level]=null;level=(level+1)%3;reset(true);restoreRouteDraft()})}else show('ИСПЫТАНИЕ НЕ ПРОЙДЕНО','Опора не выдержала.',`${failureReason} Проект сохранён — исправь его и повтори рейс.`,'Исправить мост',()=>{survey=true;reset();say('Проект сохранён. Усиль дорогу диагоналями и связями с опорами; проверь расчёт прогиба.')})}
function tick(dt){if(paused)return;time+=dt;if(storm&&!reducedMotion.matches)stormTime+=dt;if(mode==='test'){const e=roadAt(x-26.5),slope=e?(nodes[e.b].y-nodes[e.a].y)/(nodes[e.b].x-nodes[e.a].x):0;x+=72*dt/Math.sqrt(1+slope*slope);structuralStep(dt);if(mode==='test'&&x>gapRight()+220)end(true)}else if(mode==='fall'){fall+=dt;wreckStep(dt);if(fall>3.6)end(false)}if((mode==='test'||mode==='fall')&&Math.floor(time*9)!==Math.floor((time-dt)*9)){const pose=trainPose(0),dx=18.5,dy=-34;smoke.push({x:pose.x+Math.cos(pose.angle)*dx-Math.sin(pose.angle)*dy,y:pose.y+Math.sin(pose.angle)*dx+Math.cos(pose.angle)*dy,age:0})};smoke.forEach(p=>{p.age+=dt;p.x+=(storm?windLevel*25-20:-13)*dt;p.y-=22*dt});smoke=smoke.filter(p=>p.age<2.5)}
