function inspectBridge(){if(mode!=='build'||paused)return;if(survey){survey=false;$('load').textContent='НАГРУЗКА —';hud();return}roadPath=findRoadPath();if(!roadPath.length){say('Для расчёта нужна непрерывная дорога от въезда до выезда.');return}report=members.map(()=>0);let bend=0;const deck=roadNodes();for(let trainX=gapLeft();trainX<=gapRight()+180;trainX+=25){const loads=trainLoads(trainX);for(const gust of storm?[-1,0,1]:[0]){const tested=loads.slice(),side=windLoads(tested,gust),result=solve(tested,side);if(!result)continue;result.ratios.forEach((v,i)=>report[i]=Math.max(report[i],v));for(const i of deck)bend=Math.max(bend,Math.hypot(result.u[2*i],result.u[2*i+1]))}}survey=true;selected=null;clearGesture();const peak=Math.max(0,...report);$('load').textContent='РАСЧЁТ '+Math.round(peak*100)+'% · ПРОГИБ '+Math.round(bend);say((storm?'Расчёт с порывами ветра: ':'Расчёт: ')+(peak>1||bend>32?'Добавь диагонали и связь с берегами. Свободные узлы сами по себе не опоры.':'Выглядит надёжно. Проверь поездом!'));hud()}
