for(let y=0;y<256;y++)for(let x=0;x<256;x++){let value=0,weight=.55;for(const period of [8,16,32,64]){value+=smoothNoise(x/256*period,y/256*period,period)*weight;weight*=.5}tornadoNoise[y*256+x]=value}
